  constructor() {
    // 32 general-purpose registers, each 32-bit
    this.registers = new Uint32Array(32);

    // Special registers
    this.pc = 0;           // Program counter
    this.nextPc = 0;       // Next PC (for delay slot)
    this.hi = 0;           // High 32 bits of multiplication result
