    this.memory = new Map();

    // File descriptor table
    this.fileDescriptors = new Map();
    this.nextFd = 3; // Start after stdin(0), stdout(1), stderr(2)

    // Program state
    this.running = true;
    this.exitCode = 0;

    // Stats
    this.instructionCount = 0;

    // Syscall handlers
    this.initSyscallHandlers();
  }

  /**
   * Load ELF binary and initialize memory
   */
  loadELF(filename) {
    const data = fs.readFileSync(filename);

    // Parse ELF header
    const view = new DataView(data.buffer, data.byteOffset, data.length);

    // Verify ELF magic
    if (view.getUint32(0, true) !== 0x464c457f) {
      throw new Error('Invalid ELF magic number');
    }

    // Get program header info
    const e_phoff = view.getUint32(28, true);
    const e_phentsize = view.getUint16(42, true);
    const e_phnum = view.getUint16(44, true);
    const e_entry = view.getUint32(24, true);

    console.error(`[ELF] Entry point: 0x${e_entry.toString(16)}`);
    console.error(`[ELF] Program headers: ${e_phnum} at offset ${e_phoff}`);

    // Load program segments
    for (let i = 0; i < e_phnum; i++) {
      const offset = e_phoff + i * e_phentsize;
      const p_type = view.getUint32(offset, true);
      const p_offset = view.getUint32(offset + 4, true);
      const p_vaddr = view.getUint32(offset + 8, true);
      const p_filesz = view.getUint32(offset + 16, true);
      const p_memsz = view.getUint32(offset + 20, true);
      const p_flags = view.getUint32(offset + 24, true);

