        if (p_memsz > p_filesz) {
          const bssSize = p_memsz - p_filesz;
          const zeros = new Uint8Array(bssSize);
          this.writeMemory(p_vaddr + p_filesz, zeros);
        }
      }
    }

    // Initialize stack at a high address
    const stackBase = 0x7fffffff;
    const stackSize = 1024 * 1024; // 1MB stack
    this.registers[29] = stackBase - stackSize; // $sp

    // Set PC to entry point
    this.pc = e_entry;
    this.nextPc = this.pc + 4;
  }

  /**
   * Write data to memory
   */
  writeMemory(addr, data) {
    const page = Math.floor(addr / 4096);
    const offset = addr % 4096;

    if (!this.memory.has(page)) {
      this.memory.set(page, new Uint8Array(4096));
    }

    const pageData = this.memory.get(page);
    const buffer = new Uint8Array(pageData.buffer);

    if (offset + data.length <= 4096) {
      buffer.set(data, offset);
    } else {
