#!/usr/bin/env node
const fs = require('fs');

class MIPSInterpreter {
  constructor() {
    this.registers = new Uint32Array(32);
    this.pc = 0;
    this.nextPc = 0;
    this.hi = 0;
    this.lo = 0;
    this.memory = new Map();
    this.running = true;
    this.exitCode = 0;
    this.instructionCount = 0;
    this.fileDescriptors = {};
    this.nextFd = 3;
  }

  loadELF(filename) {
    const data = fs.readFileSync(filename);
    const view = new DataView(data.buffer, data.byteOffset, data.length);
    if (view.getUint32(0, true) !== 0x464c457f) throw Error('Bad ELF');
    const phoff = view.getUint32(28, true);
    const phsize = view.getUint16(42, true);
    const phnum = view.getUint16(44, true);
    const entry = view.getUint32(24, true);
    for (let i = 0; i < phnum; i++) {
      const off = phoff + i * phsize;
      const pt = view.getUint32(off, true);
      const po = view.getUint32(off + 4, true);
      const va = view.getUint32(off + 8, true);
      const fsz = view.getUint32(off + 16, true);
      const msz = view.getUint32(off + 20, true);
      if (pt === 1) {
        const seg = new Uint8Array(data.buffer, data.byteOffset + po, fsz);
        this.writeMemory(va, seg);
        if (msz > fsz) this.writeMemory(va + fsz, new Uint8Array(msz - fsz));
      }
    }
    this.registers[29] = 0x7fffffff - 1048576;
    this.pc = entry;
    this.nextPc = this.pc + 4;
  }

  writeMemory(addr, data) {
    const page = Math.floor(addr / 4096);
    const offset = addr % 4096;
    if (!this.memory.has(page)) this.memory.set(page, new Uint8Array(4096));
    const pd = this.memory.get(page);
    if (offset + data.length <= 4096) {
      pd.set(data, offset);
    } else {
      const first = 4096 - offset;
      pd.set(data.slice(0, first), offset);
      this.writeMemory(addr + first, data.slice(first));
    }
  }

  readMemory(addr, length) {
    const result = new Uint8Array(length);
    let pos = 0, ca = addr;
    while (pos < length) {
      const pg = Math.floor(ca / 4096);
      const off = ca % 4096;
      const av = Math.min(4096 - off, length - pos);
      if (this.memory.has(pg)) {
        const pd = this.memory.get(pg);
        result.set(pd.slice(off, off + av), pos);
      } else {
        result.fill(0, pos, pos + av);
      }
      pos += av;
      ca += av;
    }
    return result;
  }

  readWord32(addr) {
    const d = this.readMemory(addr, 4);
    return new DataView(d.buffer, d.byteOffset).getUint32(0, true);
  }

  writeWord32(addr, value) {
    const b = new Uint8Array(4);
